prompt:
Create unit `tasks` and implement `all_done`: the array holds job states of the `u4` unit; return whether every job is in a terminal state (2 or 3). The contract must state the result exactly.

Required signature (in unit `tasks`):
fn all_done(a: &[i64]) -> (r: bool)

reference.code:
spec fn done_below(a: &[i64], n: usize) -> bool { forall|k: usize| k < n ==> #[trigger] a[k] == 2 || a[k] == 3 }

spec fn done_spec(a: &[i64], r: bool) -> bool { r == (forall|k: usize| k < a.len() ==> #[trigger] a[k] == 2 || a[k] == 3) }

#[effects(pure)]
#[uses(done_below, done_spec, u4::d047)]
fn all_done(a: &[i64]) -> (r: bool)
    ensures done_spec(a, r),
{
    let mut k: usize = 0;
    while k < a.len() && u4::d040(a[k])
        invariant k <= a.len(), done_below(a, k),
        decreases a.len() - k,
    {
        k = k + 1;
    }
    k >= a.len()
}

